// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PENNY_BY_PENNY} from "../src/PENNY_BY_PENNY.sol";

contract InvMutTest is Test {
    PENNY_BY_PENNY c;

    function setUp() public { c = new PENNY_BY_PENNY(); }

    function testFuzz_property(uint256 lockTime) public {
        vm.assume(lockTime < 2 ** 200);
        RealLog log = new RealLog();
        Caller caller = new Caller(c, address(log));
        vm.deal(address(caller), 1);
        bool ok;
        try caller.go(lockTime) { ok = true; } catch { ok = false; }
        assertTrue(ok);
    }
}

contract RealLog {
    function AddMessage(address, uint, string memory) external pure {}
}

contract Caller {
    PENNY_BY_PENNY public c;
    address public log;
    constructor(PENNY_BY_PENNY _c, address _log) { c = _c; log = _log; }
    function go(uint256 lockTime) external {
        c.SetLogFile(log);
        c.Put{value: 1}(lockTime);
    }
    fallback() external { revert(); }
}
